package com.cpf.starter.ibmmq;import com.cpf.starter.base.*;import com.cpf.starter.messaging.reliability.CpfNamedBrokerClient;import jakarta.jms.ConnectionFactory;import java.util.Map;import org.springframework.beans.factory.SmartInitializingSingleton;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.jms.core.JmsTemplate;
@AutoConfiguration @EnableConfigurationProperties(CpfIbmMqProperties.class) @ConditionalOnProperty(prefix="cpf.messaging.ibm-mq",name="enabled",havingValue="true") public class CpfIbmMqAutoConfiguration {@Bean SmartInitializingSingleton cpfIbmMqDriverBoundary(CpfIbmMqProperties p,ConnectionFactory cf){return ()->{p.validate();String name=cf.getClass().getName();if(!name.toLowerCase(java.util.Locale.ROOT).contains("mq"))throw new IllegalStateException("IBM MQ requires customer-provided IBM MQ JMS ConnectionFactory: "+name);};}@Bean JmsTemplate cpfIbmMqJmsTemplate(ConnectionFactory cf){JmsTemplate t=new JmsTemplate(cf);t.setSessionTransacted(true);return t;}@Bean CpfIbmMqBrokerClient cpfIbmMqBrokerClient(JmsTemplate cpfIbmMqJmsTemplate,CpfIbmMqProperties p){return new CpfIbmMqBrokerClient(cpfIbmMqJmsTemplate,p);}@Bean CpfNamedBrokerClient cpfIbmMqNamedBrokerClient(CpfIbmMqBrokerClient c,CpfIbmMqProperties p,CpfCapabilityBindingRegistry r){r.register(new CpfCapabilityBinding("messaging",p.getBindingName(),"ibm-mq",p.isDefaultBinding(),Map.of("queueManager",p.getQueueManager(),"destination",p.getDestination(),"tls",Boolean.toString(p.isTlsRequired()))));return new CpfNamedBrokerClient(p.getBindingName(),"ibm-mq",p.isDefaultBinding(),c);}}
